import urllib.request,urllib.error,json,hashlib
base="https://app.ontrackegy.com/saas/mobile/updates/"
out={}
try:
 with urllib.request.urlopen(urllib.request.Request(base+"latest.json",headers={"Cache-Control":"no-cache","User-Agent":"OnTrack-OTA5-Verify"}),timeout=8) as r:out["manifest_http"]=r.status;raw=r.read(16384)
 meta=json.loads(json.loads(raw)["payload"]);out["revision"]=meta["revision"]
 with urllib.request.urlopen(base+meta["file"],timeout=8) as r:out["asset_http"]=r.status;body=r.read(524289)
 out["sha_matches"]=hashlib.sha256(body).hexdigest()==meta["sha256"];out["size_matches"]=len(body)==meta["size"]
except Exception as e:out["error"]=type(e).__name__;out["http"]=getattr(e,"code",None)
print(json.dumps(out))
